import { workflow, node, trigger, sticky, expr, newCredential, ifElse, switchCase, languageModel, memory } from '@n8n/workflow-sdk';

const uploadChunk = trigger({ type: 'n8n-nodes-base.webhook', version: 2.1, config: { name: 'Upload Chunk', parameters: { httpMethod: 'POST', path: "Y2Workplace/deploy-ui-chunk", responseMode: 'responseNode' }, position: [0, 0] }, output: [{ body: { action: 'chunk', page: 'ysquare', seq: 1, total: 5, chunk: '<!DOCTYPE html>...' } }] });
const validateChunk = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Validate Chunk', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Chunked page upload used when the deploy endpoint cannot be reached directly: chunks are stored in ys_ui_chunks, then\n// 'assemble' concatenates them into ys_ui_pages. Every step returns md5 + length so the caller can verify each piece.\nconst b = $input.first().json.body || {};\nconst action = String(b.action || 'chunk');\nconst page = String(b.page || 'ysquare');\nif (!/^[a-z0-9-]{1,40}$/.test(page)) throw new Error('bad page slug');\nif (action === 'reset') return [{ json: { sql: 'DELETE FROM ys_ui_chunks WHERE page = $1 RETURNING seq', params: [page], action } }];\nif (action === 'assemble') {\n  const total = Number(b.total || 0);\n  return [{ json: { action, sql: \"WITH a AS (SELECT string_agg(chunk, '' ORDER BY seq) AS html, count(*) AS n FROM ys_ui_chunks WHERE page = $1), u AS (INSERT INTO ys_ui_pages (page, html, updated_at, updated_by) SELECT $1, a.html, now(), 'chunk-upload' FROM a WHERE a.n = $2 ON CONFLICT (page) DO UPDATE SET html = EXCLUDED.html, updated_at = now(), updated_by = EXCLUDED.updated_by RETURNING md5(html) AS page_md5, length(html) AS page_len, updated_at) SELECT (SELECT n FROM a) AS chunks, (SELECT page_md5 FROM u) AS page_md5, (SELECT page_len FROM u) AS page_len, (SELECT updated_at FROM u) AS updated_at\", params: [page, total] } }];\n}\nconst seq = Number(b.seq); const chunk = typeof b.chunk === 'string' ? b.chunk : '';\nif (!(seq >= 1 && seq <= 200) || !chunk) throw new Error('seq (1..200) and chunk are required');\nreturn [{ json: { action, sql: 'INSERT INTO ys_ui_chunks (page, seq, chunk) VALUES ($1, $2, $3) ON CONFLICT (page, seq) DO UPDATE SET chunk = EXCLUDED.chunk RETURNING seq, md5(chunk) AS chunk_md5, length(chunk) AS chunk_len', params: [page, seq, chunk] } }];" }, position: [224, 0] }, output: [{ action: 'chunk', sql: 'INSERT ...', params: [] }] });
const ensureChunks = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Ensure Chunk Table', parameters: { operation: 'executeQuery', query: 'CREATE TABLE IF NOT EXISTS ys_ui_chunks (page text NOT NULL, seq int NOT NULL, chunk text NOT NULL, PRIMARY KEY (page, seq))', options: {} }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [448, 0] }, output: [{}] });
const runUpload = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Run Upload SQL', parameters: { operation: 'executeQuery', query: expr("{{ $('Validate Chunk').first().json.sql }}"), options: { queryReplacement: expr("{{ $('Validate Chunk').first().json.params }}") } }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [672, 0] }, output: [{ seq: 1, chunk_md5: 'abc', chunk_len: 17000 }] });
const uploadResult = node({ type: 'n8n-nodes-base.respondToWebhook', version: 1.5, config: { name: 'Upload Result', parameters: { respondWith: 'json', responseBody: expr('{{ $json }}') }, position: [896, 0] }, output: [{}] });
const note = sticky("## Y Square - Upload UI Page (chunked)\nHelper for publishing the page from environments that cannot reach the deploy endpoint directly: run this workflow with webhook data {action:'chunk', page, seq, total, chunk} once per piece, then {action:'assemble', page, total}. Each call returns md5 and length so every piece can be verified. Not meant to be published: it has no key check and is executed manually (test mode) only.", [validateChunk, runUpload], { color: 5 });
export default workflow('ysquare-upload-ui-chunked', 'Y Square - Upload UI Page (chunked)')
  .add(uploadChunk).to(validateChunk).to(ensureChunks).to(runUpload).to(uploadResult);
